<script setup>
import { ref, computed, reactive, onMounted, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useWidgets } from '@store/widgets';
import { Group, Tabs, InputLabel, InputGroup, IconUploader, Text, Button, Select, Toggle, NewBadge, Textarea, ColorPicker, Spin, MessagePreset, Tooltip, ProBadge } from '@components';
import API from '@util/API'
import { useTranslation } from '../../composables/useTranslation';
import { useUpgrade } from '@store/Upgrade';

const { t } = useTranslation();

const state = reactive({})
const $widget = useWidgets();
const { fields: widgetFieldsRef } = storeToRefs($widget);

const formychat_admin_vars = window.formychat_admin_vars || {};

// reCAPTCHA config (only visible when FormyChat form is selected).
// Use getter to read current values - formychat_admin_vars is updated after save.
const getRc = () => (formychat_admin_vars.recaptcha || {})
const recaptcha = reactive({
    enabled: getRc().enabled || false,
    site_key: getRc().site_key || '',
    secret_key: '',
    version: getRc().version || 'v2'
});

const recaptchaVersionOptions = computed(() => [
    { value: 'v2', name: t('recaptcha_version_v2'), label: t('recaptcha_version_v2') },
    { value: 'v3', name: t('recaptcha_version_v3'), label: t('recaptcha_version_v3') }
]);

const SECRET_KEY_MASK = '••••••••••••••••';
const userClearedSecretKey = ref(false);
const secretKeyDisplay = computed({
    get() {
        if ($widget.recaptchaSecretKeyConfigured && !recaptcha.secret_key && !userClearedSecretKey.value) {
            return SECRET_KEY_MASK;
        }
        return recaptcha.secret_key;
    },
    set(val) {
        const isMaskOrEmpty = val === '' || val === SECRET_KEY_MASK || /^•+$/.test(val);
        recaptcha.secret_key = isMaskOrEmpty ? '' : val;
        userClearedSecretKey.value = isMaskOrEmpty;
    }
});

// Cloudflare Turnstile (same scope as reCAPTCHA; only one should be active).
const getTs = () => (formychat_admin_vars.turnstile || {})
const turnstile = reactive({
    enabled: getTs().enabled || false,
    site_key: getTs().site_key || '',
    secret_key: ''
})
const userClearedTurnstileSecret = ref(false)
const turnstileSecretDisplay = computed({
    get() {
        if ($widget.turnstileSecretKeyConfigured && !turnstile.secret_key && !userClearedTurnstileSecret.value) {
            return SECRET_KEY_MASK;
        }
        return turnstile.secret_key;
    },
    set(val) {
        const isMaskOrEmpty = val === '' || val === SECRET_KEY_MASK || /^•+$/.test(val);
        turnstile.secret_key = isMaskOrEmpty ? '' : val;
        userClearedTurnstileSecret.value = isMaskOrEmpty;
    }
})

const errors = computed(() => $widget.errors || {});

const whatsapp = ref($widget.currentWidget.config?.whatsapp || {})
const icon = ref($widget.currentWidget.config?.icon || {})
const form = ref($widget.currentWidget.config?.form || {})
const cta = ref($widget.currentWidget.config?.cta || {})
const email = ref($widget.currentWidget.config?.email || {})

// Forms.
const cf7 = ref($widget.currentWidget.config?.cf7 || {})

const sizes = computed(() => ({
    'small': t('small'),
    'medium': t('medium'),
    'large': t('large'),
    'custom': t('custom'),
}));

const positions = computed(() => ({
    'left': t('left'),
    'right': t('right'),
    'custom': t('custom'),
}));

const admin_email = formychat_admin_vars.site.admin_email || '';

const allForms = formychat_admin_vars.data.forms || {}; 

// Form Mode.
const setFormMode = mode => {

    // Locked (Pro) form integration — show upgrade prompt instead of switching.
    if (allForms[mode]?.locked && !formychat_admin_vars.is_premium) {
        return useUpgrade().show()
    }

    const customForms = Object.keys(allForms).filter(mode => mode !== 'formychat');

    // Reset errors.
    customForms.forEach(mode => {
        $widget.setError(mode + 'NotActivated', false)
        $widget.setError(mode + 'NotInstalled', false)
    })

    if (mode === 'formychat') {
        form.value.mode = mode
        $widget.fetchFields()
        return;
    }

    // Check if the form is installed and activated.
    if (customForms.includes(mode)) {
        if (!formychat_admin_vars.additional[mode].is_installed) {
            return $widget.setError(mode + 'NotInstalled')
        }

        if (!formychat_admin_vars.additional[mode].is_active) {
            return $widget.setError(mode + 'NotActivated')
        }

        // Set form.mode_form_id if not set.
        if (!form.value[mode + '_id']) {
            form.value[mode + '_id'] = $widget.contents.forms[mode][0]?.value || ''
        }
    }

    // Load form fields.
    form.value.mode = mode
    $widget.fetchFields()
}

const isLocked = computed(() => !formychat_admin_vars.is_premium)

const toggleDeviceVisibility = (device) => {
    if (isLocked.value) return

    // Get current values (default to true if undefined)
    const currentDesktop = icon.value.show_on_desktop !== false
    const currentMobile = icon.value.show_on_mobile !== false

    if (device === 'desktop') {
        // Don't allow disabling if mobile is also disabled
        if (currentDesktop && !currentMobile) return
        icon.value.show_on_desktop = !currentDesktop
    } else {
        // Don't allow disabling if desktop is also disabled
        if (currentMobile && !currentDesktop) return
        icon.value.show_on_mobile = !currentMobile
    }
}


// Activate CF7
const activatePlugin = async (plugin = 'cf7', action = 'install') => {
    state.pluginActivating = action;

    await API.get('action?action=activate_plugin&plugin=' + plugin);

    formychat_admin_vars.additional[plugin].is_active = true
    formychat_admin_vars.additional[plugin].is_installed = true

    setFormMode(plugin)
    await $widget.fetchContents();
    form.value[plugin + '_form_id'] = $widget.contents.forms[plugin].length > 0 ? $widget.contents.forms[plugin][0]?.value : ''
    // Load CF7 form.
    state.pluginActivating = false;
}

const YouTubeId = ref('')

// Forms.
const forms = formychat_admin_vars.data.forms || {}

// Sync recaptcha to store when FormyChat form is selected (for save).
watch(() => form.value.mode, (mode) => {
    if (mode === 'formychat') {
        const rc = getRc()
        recaptcha.enabled = rc.enabled || false
        recaptcha.site_key = rc.site_key || ''
        recaptcha.version = rc.version || 'v2'
        recaptcha.secret_key = ''
        userClearedSecretKey.value = false
        $widget.setRecaptchaOptions(recaptcha)

        const ts = getTs()
        turnstile.enabled = ts.enabled || false
        turnstile.site_key = ts.site_key || ''
        turnstile.secret_key = ''
        userClearedTurnstileSecret.value = false
        $widget.setTurnstileOptions(turnstile)
    }
}, { immediate: true })

watch(recaptcha, (val) => {
    if (form.value.mode === 'formychat') {
        $widget.setRecaptchaOptions({ ...val })
    }
}, { deep: true })

watch(turnstile, (val) => {
    if (form.value.mode === 'formychat') {
        $widget.setTurnstileOptions({ ...val })
    }
}, { deep: true })

watch(() => recaptcha.enabled, (on) => {
    if (form.value.mode !== 'formychat') return
    if (on && turnstile.enabled) {
        turnstile.enabled = false
    }
})

watch(() => turnstile.enabled, (on) => {
    if (form.value.mode !== 'formychat') return
    if (on && recaptcha.enabled) {
        recaptcha.enabled = false
    }
})

const defaultCustomDropdown = () => ({
    enabled: true,
    label: 'Dropdown',
    name: 'dropdown',
    required: false,
    placeholder: '- Select -',
    position: 'before_message',
    default_value: '',
    options: [
        { value: 'option_1', label: 'Option 1' },
        { value: 'option_2', label: 'Option 2' },
    ],
})

const ensureCustomDropdown = () => {
    if (!form.value.custom_dropdown || typeof form.value.custom_dropdown !== 'object') {
        form.value.custom_dropdown = defaultCustomDropdown()
    }
    if (!Array.isArray(form.value.custom_dropdown.options)) {
        form.value.custom_dropdown.options = []
    }
    if (form.value.custom_dropdown.default_value === undefined) {
        form.value.custom_dropdown.default_value = ''
    }
}

const customDropdownPositionOptions = computed(() => [
    { value: 'after_name', name: t('custom_dropdown_position_after_name'), label: t('custom_dropdown_position_after_name') },
    { value: 'after_email', name: t('custom_dropdown_position_after_email'), label: t('custom_dropdown_position_after_email') },
    { value: 'after_phone', name: t('custom_dropdown_position_after_phone'), label: t('custom_dropdown_position_after_phone') },
    { value: 'before_message', name: t('custom_dropdown_position_before_message'), label: t('custom_dropdown_position_before_message') },
])

const formychatMessagePresetFields = computed(() => {
    ensureCustomDropdown()
    const raw = widgetFieldsRef.value
    const base = raw && typeof raw === 'object' ? { ...raw } : {}
    const fd = form.value.custom_dropdown
    if (form.value.mode === 'formychat' && fd?.enabled && fd.name) {
        const lbl = fd.label && String(fd.label).trim() ? fd.label : fd.name
        base[fd.name] = lbl
    }
    return base
})

const addCustomDropdownOption = () => {
    ensureCustomDropdown()
    const n = form.value.custom_dropdown.options.length + 1
    form.value.custom_dropdown.options.push({ label: `Option ${n}`, value: `option_${n}` })
}

const dropdownMinOptionToast = ref(false)
let dropdownToastTimer = null

// Controls visibility of the "value" column in the options list.
// When hidden, each option's value is kept in sync with its label.
const showValueFields = ref(false)

watch(showValueFields, (show) => {
    if (!show) {
        form.value.custom_dropdown?.options?.forEach((opt) => {
            opt.value = opt.label
        })
    }
})

watch(
    () => form.value.custom_dropdown?.options?.map((o) => o.label),
    (newLabels) => {
        if (!showValueFields.value && newLabels) {
            newLabels.forEach((label, idx) => {
                if (form.value.custom_dropdown?.options?.[idx]) {
                    form.value.custom_dropdown.options[idx].value = label
                }
            })
        }
    }
)

const removeCustomDropdownOption = (idx) => {
    ensureCustomDropdown()
    if (form.value.custom_dropdown.options.length <= 1) {
        dropdownMinOptionToast.value = true
        clearTimeout(dropdownToastTimer)
        dropdownToastTimer = setTimeout(() => { dropdownMinOptionToast.value = false }, 3000)
        return
    }
    form.value.custom_dropdown.options.splice(idx, 1)
}

const DROPDOWN_TEMPLATE_LINE_RE = /^\s*Dropdown:\s*\{[^}]+\}\s*$/

const stripDropdownTemplateLines = (text) => {
    if (!text || typeof text !== 'string') {
        return ''
    }
    const lines = text.split('\n')
    const filtered = lines.filter((line) => !DROPDOWN_TEMPLATE_LINE_RE.test(line))
    return filtered.join('\n').replace(/\n{3,}/g, '\n\n')
}

const appendDropdownTemplateLine = (text, fieldKey) => {
    const key = (fieldKey && String(fieldKey).trim()) || 'dropdown'
    const line = `Dropdown: {${key}}`
    const current = typeof text === 'string' ? text : ''
    const trimmedLines = current.split('\n').map((l) => l.trimEnd())
    if (trimmedLines.some((l) => l.trim() === line)) {
        return current
    }
    if (!current.length) {
        return `${line}\n`
    }
    const endsWithNl = current.endsWith('\n')
    return `${current}${endsWithNl ? '' : '\n'}${line}\n`
}

watch(
    () => !!form.value.custom_dropdown?.enabled,
    (enabled, wasEnabled) => {
        if (form.value.mode !== 'formychat') {
            return
        }
        if (wasEnabled === undefined) {
            return
        }
        ensureCustomDropdown()
        const tmpl = whatsapp.value.message_template
        if (enabled) {
            const key = form.value.custom_dropdown.name || 'dropdown'
            whatsapp.value.message_template = appendDropdownTemplateLine(tmpl, key)
        } else {
            whatsapp.value.message_template = stripDropdownTemplateLines(tmpl)
        }
    }
)

watch(() => form.value.mode, (mode) => {
    if (mode === 'formychat') {
        ensureCustomDropdown()
    }
}, { immediate: true })

watch(() => $widget.currentWidget?.id, () => {
    ensureCustomDropdown()
})

// Adjust cf7_id.
onMounted(() => {
    ensureCustomDropdown()
    if (cf7.value.form_id) {
        form.value.cf7_id = cf7.value.form_id

        // Reset cf7_id.
        cf7.value.form_id = ''
    }

    if (form.value.mode === 'formychat') {
        const rc = getRc()
        recaptcha.enabled = rc.enabled || false
        recaptcha.site_key = rc.site_key || ''
        recaptcha.version = rc.version || 'v2'
        userClearedSecretKey.value = false
        $widget.setRecaptchaOptions(recaptcha)

        const ts = getTs()
        turnstile.enabled = ts.enabled || false
        turnstile.site_key = ts.site_key || ''
        turnstile.secret_key = ''
        userClearedTurnstileSecret.value = false
        $widget.setTurnstileOptions(turnstile)
    }

    $widget.fetchFields()
})


</script>
<template>
    <div class="w-full h-full">
        <div class="flex flex-col gap-10 w-full">
            <!-- Customize Icon  -->
            <Group :title="t('customize_icon')" :gap="false">
                <InputGroup>
                    <InputLabel :hints="t('select_icon_size_hint')" locked> {{ t('custom_icon') }}  </InputLabel>
                    <IconUploader :class="{ 'formychat-locked child:pointer-events-none child:opacity-60': isLocked }"
                        :default="Image('whatsapp.svg')" v-model="icon.image_url"
                        v-model:custom="icon.image_url_custom" />
                </InputGroup>
                <InputGroup>
                    <InputLabel :hints="t('select_icon_size_hint')"> {{ t('icon_size') }} </InputLabel>
                    <Tabs :options="sizes" :locked="['custom']" width="83px" class="bg-gray-50" v-model="icon.size" />
                </InputGroup>
                <InputGroup :condition="icon.size == 'custom'">
                    <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_icon_size') }} </InputLabel>
                    <div class="w-full flex items-center justify-between gap-2">
                        <input class="formychat-slider" type="range" v-model="icon.size_custom" min="20" max="300">
                        <span class="w-16">{{ icon.size_custom }}px</span>
                    </div>
                </InputGroup>
                <InputGroup>
                    <InputLabel :hints="t('icon_position_hint')"> {{ t('icon_position') }} </InputLabel>
                    <Tabs :options="positions" :locked="['custom']" width="83px" class="bg-gray-50"
                        v-model="icon.position" />
                </InputGroup>
                <InputGroup :condition="icon.position == 'custom'">
                    <InputLabel :hints="t('select_icon_position_hint')"> {{ t('custom_icon_position') }} </InputLabel>
                    <div class="flex items-center gap-6 flex-wrap">
                        <div v-for="direction in ['left', 'right', 'top', 'bottom']" :key="direction"
                            class="flex flex-col gap-2">
                            <InputLabel class="capitalize text-gray-500" :for="`icon_position_custom_${direction}`">{{
                                direction }}</InputLabel>
                            <div class="flex items-center gap-1 w-24"><Text :id="`icon_position_custom_${direction}`"
                                    type="number" class="text-sm w-20" placeholder="auto"
                                    v-model="icon.position_custom[direction]" /><span
                                    v-if="icon.position_custom[direction] !== ''" class="text-gray-400">px</span></div>
                        </div>
                    </div>
                </InputGroup>
                <InputGroup>
                    <InputLabel :hints="t('display_widget_hint')"> {{ t('display_floating_widget_on') }} </InputLabel>
                    <div class="flex items-center gap-3 text-slate-600 text-sm">
                        <div class="bg-white px-4 py-2 flex items-center gap-2 ring rounded cursor-pointer relative transition"
                            :class="{
                                'ring-indigo-600': icon.show_on_desktop !== false,
                                'ring-slate-100 hover:ring-slate-300': icon.show_on_desktop === false,
                                'formychat-locked': isLocked
                            }"
                            @click.prevent="toggleDeviceVisibility('desktop')">
                            <svg xmlns="http://www.w3.org/2000/svg" class="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
                                <path stroke-linecap="round" stroke-linejoin="round" d="M9 17.25v1.007a3 3 0 0 1-.879 2.122L7.5 21h9l-.621-.621A3 3 0 0 1 15 18.257V17.25m6-12V15a2.25 2.25 0 0 1-2.25 2.25H5.25A2.25 2.25 0 0 1 3 15V5.25m18 0A2.25 2.25 0 0 0 18.75 3H5.25A2.25 2.25 0 0 0 3 5.25m18 0V12a2.25 2.25 0 0 1-2.25 2.25H5.25A2.25 2.25 0 0 1 3 12V5.25" />
                            </svg>
                            <span class="font-medium text-xs">{{ t('desktop') }}</span>
                            <transition name="bounce">
                                <svg v-if="icon.show_on_desktop !== false" xmlns="http://www.w3.org/2000/svg"
                                    class="w-4 fill-indigo-500" viewBox="0 0 16 16">
                                    <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z" />
                                </svg>
                            </transition>
                        </div>
                        <div class="bg-white px-4 py-2 flex items-center gap-2 ring rounded cursor-pointer relative transition"
                            :class="{
                                'ring-indigo-600': icon.show_on_mobile !== false,
                                'ring-slate-100 hover:ring-slate-300': icon.show_on_mobile === false,
                                'formychat-locked': isLocked
                            }"
                            @click.prevent="toggleDeviceVisibility('mobile')">
                            <svg xmlns="http://www.w3.org/2000/svg" class="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
                                <path stroke-linecap="round" stroke-linejoin="round" d="M10.5 1.5H8.25A2.25 2.25 0 0 0 6 3.75v16.5a2.25 2.25 0 0 0 2.25 2.25h7.5A2.25 2.25 0 0 0 18 20.25V3.75a2.25 2.25 0 0 0-2.25-2.25H13.5m-3 0V3h3V1.5m-3 0h3m-3 18.75h3" />
                            </svg>
                            <span class="font-medium text-xs">{{ t('mobile') }}</span>
                            <transition name="bounce">
                                <svg v-if="icon.show_on_mobile !== false" xmlns="http://www.w3.org/2000/svg"
                                    class="w-4 fill-indigo-500" viewBox="0 0 16 16">
                                    <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z" />
                                </svg>
                            </transition>
                        </div>
                    </div>
                </InputGroup>
            </Group>
            <!-- Divider  -->
            <div class="border-b-2 border-dashed border-gray-200 rounded"></div>
            <!-- Call to action  -->
            <Group :title="t('call_to_action')" :gap="false">
                <InputGroup>
                    <Toggle v-model="cta.enabled">{{ t('show_call_to_action') }}</Toggle>
                </InputGroup>
                <InputGroup :condition="cta.enabled">
                    <InputLabel> {{ t('call_to_action_text') }} </InputLabel>
                    <Text :placeholder="t('call_to_action_text')" v-model="cta.text" />
                </InputGroup>
                <InputGroup :condition="cta.enabled">
                    <InputLabel :hints="t('select_icon_size_hint')" locked>{{ t('cta_style') }}</InputLabel>
                    <div class="flex items-center gap-3"
                        :class="{ 'opacity-60 formychat-locked child:pointer-events-none': isLocked }">
                        <ColorPicker v-model="cta.color"> {{ t('text_color') }} </ColorPicker>
                        <ColorPicker v-model="cta.background_color"> {{ t('background_color') }} </ColorPicker>
                    </div>
                </InputGroup>
                <InputGroup :condition="cta.enabled">
                    <InputLabel :hints="t('select_icon_size_hint')"> {{ t('text_size') }}</InputLabel>
                    <Tabs class="bg-gray-50" :options="sizes" width="85px" v-model="cta.size" :locked="['custom']" />
                </InputGroup>
                <InputGroup :condition="cta.enabled && cta.size == 'custom'">
                    <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_text_size') }} </InputLabel>
                    <div class="w-full flex items-center justify-between gap-2">
                        <input class="formychat-slider" type="range" min="8" max="72" v-model="cta.size_custom">
                        <span class="w-16">{{ cta.size_custom || 8 }}px</span>
                    </div>
                </InputGroup>
            </Group>
            <!-- Divider  -->
            <div class="border-b-2 border-dashed border-gray-200 rounded"></div>
            <!-- Customize Form  -->
            <Group :title="t('customize_form')" :gap="false" id="customize_form"
                v-if="!(whatsapp.agent_mode === 'agents' && whatsapp.click_agent_to_redirect)">
                <InputGroup>
                    <InputLabel> {{ t('choose_message_source') }} </InputLabel>
                    <div class="flex items-center flex-wrap gap-5  text-slate-600 text-medium text-sm">
                        <div class="bg-white w-28 h-24 flex flex-col items-center gap-1 justify-center ring rounded cursor-pointer relative transition"
                            v-for="(label, mode) in forms" @click.prevent="setFormMode(mode)"
                            :class="{ 'ring-indigo-600': form.mode == mode, 'ring-slate-100 hover:ring-slate-300': form.mode !== mode, 'opacity-60': label.locked && !formychat_admin_vars.is_premium }">
                            <ProBadge v-if="label.locked && !formychat_admin_vars.is_premium" class="absolute -top-2 -right-2" />
                            <img :src="label.logo" class="w-10">
                            <span class="w-full text-center font-medium text-xs">{{ label.label }}</span>
                            <transition name="bounce">
                                <svg v-if="form.mode == mode" xmlns="http://www.w3.org/2000/svg"
                                    class="w-5 fill-indigo-500 text-white absolute right-2 top-2" viewBox="0 0 16 16">
                                    <path
                                        d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z" />
                                </svg>
                            </transition>
                        </div>
                    </div>
                </InputGroup>
                <!-- When CF7 is not installed or activated.  -->
                <transition name="no">
                    <div v-if="errors.cf7NotActivated || errors.cf7NotInstalled"
                        class="flex items-start gap-5 px-6 py-5 bg-gray-100 border border-gray-200 rounded text-gray-700 w-full break-words">
                        <svg xmlns="http://www.w3.org/2000/svg" class="fill-current w-10" viewBox="0 0 16 16">
                            <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16" />
                            <path
                                d="M7.002 11a1 1 0 1 1 2 0 1 1 0 0 1-2 0M7.1 4.995a.905.905 0 1 1 1.8 0l-.35 3.507a.552.552 0 0 1-1.1 0z" />
                        </svg>
                        <p class="font-medium text-[13px] tracking leading-relaxed" v-html="t('plugin_not_ready_error', {
                                plugin: 'Contact Form 7',
                                status: `<strong class='font-bold'>${errors.CF7NotInstalled ? t('installed_status') : t('activated_status')}</strong>`,
                                action: errors.CF7NotInstalled ? t('install_and_activate') : t('activate')
                            })"></p>
                        <div>
                            <Button :class="{ 'opacity-60 pointer-events-none': state.pluginActivating }"
                                @click.prevent="activatePlugin('cf7')">
                                <span class="flex items-center gap-2" v-if="state.pluginActivating">
                                    {{ errors.cf7NotInstalled ? t('installing') : t('activating') }}
