                </InputGroup>
                <!-- reCAPTCHA / Turnstile (only when FormyChat form is selected) -->
                <InputGroup v-if="form.mode == 'formychat'" class="space-y-4">
                    <div class="space-y-4">
                        <div class="space-y-2">
                            <div class="flex items-center gap-3">
                                <Toggle v-model="recaptcha.enabled" :hints="t('recaptcha_enable_hint')">
                                    {{ t('enable_recaptcha') }}
                                </Toggle>
                                <NewBadge />
                            </div>
                            <p
                                v-if="recaptcha.enabled"
                                class="text-xs text-slate-600 leading-relaxed pl-0.5 max-w-xl"
                            >
                                {{ t('recaptcha_setup_help') }}
                                <a
                                    href="https://docs.google.com/document/d/1Mpl0PDQyCmC34oS22r7nlDvfLkFoUjgaLzpGZDx2nGM/edit?usp=sharing"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    class="text-indigo-600 hover:text-indigo-800 font-medium underline decoration-indigo-300 underline-offset-2"
                                >{{ t('recaptcha_setup_documentation') }}</a>.
                            </p>
                        </div>
                        <div v-if="recaptcha.enabled" class="space-y-3 rounded-lg p-4" style="background: #f3f4f6; border: 1px solid #e5e7eb;">
                            <div>
                                <InputLabel class="mb-1 !items-start" semibold :hints="t('recaptcha_version_tooltip')">
                                    {{ t('recaptcha_version_label') }}
                                </InputLabel>
                                <Select v-model="recaptcha.version" :white="true" class="w-48" :options="recaptchaVersionOptions" :search="false" />
                                <p class="text-xs text-gray-500 mt-1">{{ t('recaptcha_version_hint') }}</p>
                            </div>
                            <div>
                                <InputLabel class="mb-1 !items-start" semibold :hints="t('recaptcha_site_key_tooltip')">
                                    {{ t('recaptcha_site_key_label') }}
                                </InputLabel>
                                <Text :white="true" v-model="recaptcha.site_key" :placeholder="t('recaptcha_site_key_placeholder')" type="text" />
                                <p class="text-xs text-gray-500 mt-1">{{ t('recaptcha_site_key_hint') }}</p>
                            </div>
                            <div>
                                <InputLabel class="mb-1 !items-start" semibold :hints="t('recaptcha_secret_key_tooltip')">
                                    {{ t('recaptcha_secret_key_label') }}
                                </InputLabel>
                                <Text :white="true" v-model="secretKeyDisplay"
                                    :placeholder="$widget.recaptchaSecretKeyConfigured ? '' : t('recaptcha_secret_key_placeholder')"
                                    type="password" />
                                <p class="text-xs text-gray-500 mt-1">{{ t('recaptcha_secret_key_hint') }}</p>
                            </div>
                        </div>
                        <div class="space-y-2">
                            <div class="flex items-center gap-3">
                                <Toggle v-model="turnstile.enabled" :hints="t('turnstile_enable_hint')">
                                    {{ t('enable_turnstile') }}
                                </Toggle>
                                <NewBadge />
                            </div>
                            <p
                                v-if="turnstile.enabled"
                                class="text-xs text-slate-600 leading-relaxed pl-0.5 max-w-xl"
                            >
                                {{ t('turnstile_setup_help') }}
                                <a
                                    href="https://docs.google.com/document/d/1tl2R3RXKo-pnauFKtJJSbU-5MedG7gI1FuYsrsTCaRY/edit?usp=sharing"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    class="text-indigo-600 hover:text-indigo-800 font-medium underline decoration-indigo-300 underline-offset-2"
                                >{{ t('turnstile_setup_documentation') }}</a>.
                            </p>
                        </div>
                        <div v-if="turnstile.enabled" class="space-y-3 rounded-lg p-4" style="background: #f3f4f6; border: 1px solid #e5e7eb;">
                            <div>
                                <InputLabel class="mb-1 !items-start" semibold :hints="t('turnstile_site_key_tooltip')">
                                    {{ t('turnstile_site_key_label') }}
                                </InputLabel>
                                <Text :white="true" v-model="turnstile.site_key" :placeholder="t('turnstile_site_key_placeholder')" type="text" />
                                <p class="text-xs text-gray-500 mt-1">{{ t('turnstile_site_key_hint') }}</p>
                            </div>
                            <div>
                                <InputLabel class="mb-1 !items-start" semibold :hints="t('turnstile_secret_key_tooltip')">
                                    {{ t('turnstile_secret_key_label') }}
                                </InputLabel>
                                <Text :white="true" v-model="turnstileSecretDisplay"
                                    :placeholder="$widget.turnstileSecretKeyConfigured ? '' : t('turnstile_secret_key_placeholder')"
                                    type="password" />
                                <p class="text-xs text-gray-500 mt-1">{{ t('turnstile_secret_key_hint') }}</p>
                            </div>
                        </div>
                    </div>
                </InputGroup>
                <!-- size  -->
                <InputGroup>
                    <InputLabel> {{ t('form_size') }} </InputLabel>
                    <Tabs :options="sizes" v-model="form.size" width="85px" class="bg-gray-50" />
                </InputGroup>
                <InputGroup :condition="form.size == 'custom'">
                    <InputLabel> {{ t('custom_form_size') }} </InputLabel>
                    <div class="w-full flex items-center justify-between gap-2">
                        <input class="formychat-slider" type="range" min="100" max="1000" v-model="form.size_custom">
                        <span class="w-16">{{ form.size_custom || 300 }}px</span>
                    </div>
                </InputGroup>
                <!-- Form  -->
                <InputGroup>
                    <InputLabel> {{ t('form_title_label') }} </InputLabel>
                    <Text :placeholder="t('form_title_placeholder')" v-model="form.title" name="form_title" />
                </InputGroup>
                <InputGroup>
                    <InputLabel :hints="t('leave_blank_disable')"> {{ t('header_text') }} </InputLabel>
                    <div class="w-full">
                        <Textarea :placeholder="t('header_text_placeholder')" class="resize-y"
                            name="form_subtitle" v-model="form.subtitle" />
                    </div>
                </InputGroup>
                <InputGroup>
                    <InputLabel :hints="t('leave_blank_disable')"> {{ t('footer_text') }} </InputLabel>
                    <div class="w-full">
                        <Textarea :placeholder="t('footer_text_placeholder')" class="resize-none"
                            name="form_footer" v-model="form.footer" />
                    </div>
                </InputGroup>
                <InputGroup :condition="form.mode == 'formychat'">
                    <InputLabel> {{ t('submit_button_text') }} </InputLabel>
                    <Text :placeholder="t('submit_button_placeholder')" name="form_submit" v-model="form.submit" />
                </InputGroup>
                <InputGroup class="space-y-3" :condition="form.mode == 'formychat'">
                    <div class="flex items-center gap-3">
                        <Toggle v-model="form.show_country_code_field"
                            :hints="t('country_code_hint')" locked> {{ t('allow_country_code_select') }} {{ t('country_code') }}</Toggle>
                    </div>
                    <transition name="slide">
                        <div class="flex items-center gap-2" v-if="form.show_country_code_field">
                            <InputLabel> {{ t('default') }} {{ t('country_code') }} </InputLabel>
                            <Select v-model="form.country_code" class="w-fit" :options="$widget.contents.countries"
                                :placeholder="t('select_country')" />
                        </div>
                    </transition>
                </InputGroup>
                <InputGroup>
                    <InputLabel locked> {{ t('widget_style') }} </InputLabel>
                    <div class="flex items-center gap-4"
                        :class="{ 'opacity-60 formychat-locked child:pointer-events-none': isLocked }">
                        <ColorPicker v-model="form.text_color">{{ t('text_color') }}</ColorPicker>
                        <ColorPicker v-model="form.background_color">{{ t('background_color') }}</ColorPicker>
                    </div>
                </InputGroup>
                <InputGroup class="w-full">
                    <InputLabel>{{ t('font_family') }}</InputLabel>
                    <Select :options="$widget.contents.fonts" v-model="form.font_family" :placeholder="t('select_font')"
                        class="w-56" />
                </InputGroup>
            </Group>
            <!-- Divider  -->
            <div class="border-b-2 border-dashed border-gray-200 rounded"></div>
            <!-- Form behavior  -->
            <Group :title="t('behavior')" :gap="false">
                <InputGroup class="space-y-3">
                    <Toggle v-model="form.open_by_default" :hints="t('form_open_default_hint')">
                        {{ t('open_by_default') }}</Toggle>
                    <Toggle v-model="form.close_on_submit" :hints="t('form_close_submit_hint')">{{ t('close_form_on_submit') }}
                        {{ t('on_submit') }}</Toggle>
                </InputGroup>
            </Group>
        </div>
        <!-- YouTube Video  -->
        <transition name="fade">
            <div v-if="YouTubeId" class="absolute left-0 top-0 w-full flex h-full z-20 items-center justify-center">
                <div class="absolute top-0 left-0 w-full h-full bg-black opacity-50" @click="YouTubeId = ''"></div>
                <div class="fixed top-1/2 -translate-y-1/2 w-full max-w-xl h-96 z-50">
                    <!-- close  -->
                    <div @click="YouTubeId = ''"
                        class="absolute -top-10 -right-10 cursor-pointer w-10 h-10 flex items-center justify-center text-white hover:brightness-110 hover:scale-110 transition">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"
                            class="h-5 w-5 fill-current">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                                d="M6 18L18 6M6 6l12 12"></path>
                        </svg>
                    </div>
                    <iframe class="w-full h-full"
                        :src="'https://www.youtube.com/embed/' + YouTubeId + '?autoplay=1'"></iframe>
                </div>
            </div>
        </transition>
    </div>
</template>
